// Build the vault-reset approval email. The recipient is ALWAYS the vault owner
// read from vault_settings, never the caller's `to`: whoever holds the shared
// webhook secret must not be able to mail arbitrary addresses from the company Gmail.
const b = $('Trigger').first().json.body || {};
const owner = String($json.owner_email || '').trim();
const code = String(b.code || '');
const mins = Math.min(Math.max(parseInt(b.expires_minutes, 10) || 15, 1), 60);
const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const by = esc(String(b.requested_by || 'An admin').slice(0, 120));
const byEmail = esc(String(b.requested_by_email || '').slice(0, 120));

// Fail loudly (the Edge Function sees a 500 and drops the code) rather than
// "succeed" with nothing sent or with the code sent somewhere else.
if (!owner) throw new Error('vault-reset: no vault owner email in vault_settings');
if (b.to && String(b.to).trim().toLowerCase() !== owner.toLowerCase()) throw new Error('vault-reset: recipient mismatch');
if (!/^\d{6}$/.test(code)) throw new Error('vault-reset: malformed code');

const html = `<div style="font-family:system-ui,-apple-system,Segoe UI,Roboto,sans-serif;color:#111">
  <h2 style="margin:0 0 4px">Vault reset approval</h2>
  <p style="margin:0 0 16px;color:#666">${by}${byEmail ? ' (' + byEmail + ')' : ''} is asking to reset the DeskDev Studio vault.</p>
  <div style="padding:18px;border:1px solid #eee;border-radius:10px;text-align:center">
    <div style="font-size:32px;font-weight:700;letter-spacing:8px;font-family:ui-monospace,monospace">${code}</div>
    <div style="margin-top:6px;color:#666;font-size:13px">Expires in ${mins} minutes</div>
  </div>
  <p style="margin-top:18px;color:#111">A reset does <strong>not</strong> delete the stored credentials &mdash; they are archived, and can be restored later with the current master password. It does force a new master password and a new authenticator.</p>
  <p style="margin-top:12px;color:#b45309"><strong>If you did not expect this request, do not share the code.</strong></p>
  <p style="margin-top:20px;color:#999;font-size:12px">Sent by n8n for DeskDev Studio</p></div>`;

return [{ json: { to: owner, subject: 'DeskDev Vault reset code: ' + code, html } }];
